    """Parse a JSON fenced block, tolerating nested ``` inside JSON strings."""
    start_re = re.compile(rf"```{re.escape(fence_name)}\s*", re.IGNORECASE)
    for start in start_re.finditer(text):
        content_start = start.end()
        for fence in re.finditer(r"```", text[content_start:]):
            raw_json = text[content_start:content_start + fence.start()].strip()
            if not raw_json:
                continue
            try:
                parsed = json.loads(raw_json)
            except json.JSONDecodeError:
                repaired = re.sub(r",\s*([}\]])", r"\1", raw_json)
                try:
                    parsed = json.loads(repaired)
                except json.JSONDecodeError:
                    continue
            if isinstance(parsed, dict):
                return parsed
    return None

def _parse_edit_plan_json(raw_json: str) -> tuple[dict[str, Any] | None, str | None]:
    try:
        plan = json.loads(raw_json)
        return plan if isinstance(plan, dict) else None, "edit plan block was not a JSON object"
    except json.JSONDecodeError as exc:
        repaired = re.sub(r",\s*([}\]])", r"\1", raw_json)
        try:
            plan = json.loads(repaired)
            return plan if isinstance(plan, dict) else None, "edit plan block was not a JSON object"
        except json.JSONDecodeError:
            return None, str(exc)


def _extract_edit_plan_blocks(text: str) -> list[str]:
    starts = list(EDIT_PLAN_BLOCK_START_RE.finditer(text))
    if not starts:
        return []
    blocks: list[str] = []
    for start in starts:
        content_start = start.end()
        for fence in FENCE_RE.finditer(text, content_start):
            candidate = text[content_start:fence.start()].strip()
            if not candidate:
                continue
            plan, _error = _parse_edit_plan_json(candidate)
            if plan is not None:
                blocks.append(candidate)
                break
    return blocks

